 $$("[data-item-delete]").forEach(b=>b.onclick=async()=>{if(!confirm("למחוק את הפריט לפי כללי ההיסטוריה?"))return;try{await api("/api/items/"+encodeURIComponent(b.dataset.itemDelete)+"/delete-safe",{method:"DELETE"});toast("הפריט טופל לפי כללי המחיקה");await refresh();await renderInventory()}catch(e){toast(e.message,true)}});
 $$("[data-unit-edit]").forEach(b=>b.onclick=()=>unitDialog(b.dataset.unitEdit,b.dataset.status,b.dataset.condition));
 $$("[data-unit-transfer]").forEach(b=>b.onclick=()=>unitTransferDialog(b.dataset.unitTransfer,b.dataset.org));
