async function showQr(id){try{const data=await api("/api/item-units/"+encodeURIComponent(id)+"/qr");const d=dialog("QR ליחידה",`<div class="wide" id="pc-qr"></div><p class="wide"><strong>${esc(data.printLabel)}</strong></p><p class="wide" dir="ltr">${esc(data.target)}</p><button type="button" class="platform-action" id="pc-print-qr">הדפסה</button>`,async()=>{});const box=$("#pc-qr",d);if(typeof window.qrcode==="function"){const qr=window.qrcode(0,"M");qr.addData(data.target);qr.make();box.innerHTML=qr.createImgTag(6,8)}else box.innerHTML="<p>ספריית QR לא נטענה.</p>";$("#pc-print-qr",d).onclick=()=>window.print()}catch(e){toast(e.message,true)}}
