function parseCsv(text){
 const rows=[];let row=[],field="",quote=false;
 for(let i=0;i<text.length;i++){const ch=text[i];if(quote){if(ch==='"'&&text[i+1]==='"'){field+='"';i++}else if(ch==='"')quote=false;else field+=ch}else if(ch==='"')quote=true;else if(ch===","){row.push(field);field=""}else if(ch==="\n"){row.push(field.replace(/\r$/,""));rows.push(row);row=[];field=""}else field+=ch}
 if(field||row.length){row.push(field);rows.push(row)}if(!rows.length)return[];
 const headers=rows.shift().map(h=>h.trim().replace(/^\uFEFF/,""));return rows.filter(r=>r.some(Boolean)).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??""])));
}
function importDialog(orgs){
 const d=dialog("ייבוא מוצרים מ־CSV",`<label class="wide"><span>גמ״ח</span><select name="org" required><option value="">בחירה</option>${orgs.map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join("")}</select></label><label class="wide"><span>קובץ CSV</span><input type="file" name="file" accept=".csv,text/csv" required></label><div class="wide platform-note">כותרות נתמכות: title, category, description, condition, quantity.</div><div class="wide platform-preview" id="pc-import-preview">בחרו קובץ להצגת תצוגה מקדימה.</div><button type="submit">בדיקה וייבוא</button>`,async(f,form)=>{const file=form.elements.file.files[0],rows=parseCsv(await file.text());if(!rows.length)throw new Error("הקובץ ריק");const data=await api("/api/items/import",{method:"POST",body:{organizationId:f.get("org"),items:rows}});if(data.errors?.length)toast(`יובאו ${data.created.length}; ${data.errors.length} שורות נכשלו`,true);else toast(`יובאו ${data.created.length} פריטים`);});
 const input=$('input[type=file]',d);input.onchange=async()=>{const rows=parseCsv(await input.files[0].text());$("#pc-import-preview",d).innerHTML=`<strong>${rows.length} שורות</strong><pre>${esc(JSON.stringify(rows.slice(0,5),null,2))}</pre>`};
}
